using System;
using System.Drawing.Design;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private readonly StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: StatusStrip default renderer changed from
        // ManagerRenderMode to a system renderer. Explicitly set it to
        // preserve the .NET 8 visual style.
        _statusStrip.RenderMode = ToolStripRenderMode.ManagerRenderMode;
        Controls.Add(_statusStrip);
    }

    // .NET 9 breaking change: DropDownControl now throws ArgumentNullException
    // when passed null. Always guard with a null check.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }

    // .NET 9 breaking change: DllImport-based P/Invoke should use
    // LibraryImportAttribute with DisableRuntimeMarshalling for new
    // COM/native interop. Existing DllImport calls still work but
    // bool marshalling now defaults to 4-byte BOOL — use
    // [MarshalAs(UnmanagedType.Bool)] to be explicit.
    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool SetForegroundWindow(IntPtr hWnd);
}

